/**
 * Per-segment question forms for the audio and video widgets.
 *
 * The server renders `segment_schemes` once into a hidden
 * `<template id="segment-questions-template-{schema}">` (see
 * potato/server_utils/schemas/segment_questions.py). This clones it for the
 * segment the annotator has selected, fills it from `segment.annotations`, and
 * writes changes back there.
 *
 * ## The fields are proxies, not annotation inputs
 *
 * A form generated by the schema registry carries `class="annotation-input"`
 * and `schema` / `label_name` attributes, which is precisely what
 * `syncAnnotationsFromDOM` and the display-logic DOM collector look for. Left
 * intact, one segment's answer would be read as a top-level answer for a scheme
 * that does not exist, and several segments would overwrite each other under
 * the same key. Every clone therefore has those attributes renamed to
 * `data-segment-*` and the class removed, so the page-level collectors cannot
 * see them and the only home for the value is `segment.annotations`.
 *
 * Ids and names are namespaced by segment id for the same reason, and because
 * radio groups keyed on `name` would otherwise be shared across segments.
 */

(function () {
    'use strict';

    var ATTRIBUTES_TO_PROXY = ['schema', 'label_name', 'validation'];

    /**
     * Build the questions form for one segment.
     *
     * @param {Object} options
     * @param {string} options.schemaName   Parent audio/video scheme name.
     * @param {HTMLElement} options.container  Where the form is written.
     * @param {Object} options.segment      The segment record; gains `annotations`.
     * @param {Function} [options.onChange] Called after any answer changes.
     * @returns {boolean} Whether a form was rendered.
     */
    function renderSegmentQuestions(options) {
        var container = options.container;
        var segment = options.segment;
        if (!container || !segment) return false;

        var template = document.getElementById(
            'segment-questions-template-' + options.schemaName);
        if (!template || !template.content) return false;

        if (!segment.annotations || typeof segment.annotations !== 'object') {
            segment.annotations = {};
        }

        var form = template.content.cloneNode(true);
        var segmentKey = String(segment.id);

        neutralize(form, segmentKey);

        container.innerHTML = '';
        container.appendChild(form);

        populate(container, segment);
        bind(container, segment, options.onChange);
        return true;
    }

    /**
     * Turn a cloned annotation form into proxy widgets.
     *
     * Renames the attributes the page-level collectors key on and namespaces
     * every id/name by segment, then repoints the labels that referenced them.
     */
    function neutralize(root, segmentKey) {
        var suffix = '__seg_' + segmentKey.replace(/[^A-Za-z0-9_-]/g, '_');
        var idMap = {};

        root.querySelectorAll('[id]').forEach(function (el) {
            var oldId = el.id;
            var newId = oldId + suffix;
            idMap[oldId] = newId;
            el.id = newId;
        });

        root.querySelectorAll('label[for]').forEach(function (label) {
            var target = label.getAttribute('for');
            if (idMap[target]) label.setAttribute('for', idMap[target]);
        });

        root.querySelectorAll('input, select, textarea').forEach(function (field) {
            ATTRIBUTES_TO_PROXY.forEach(function (attribute) {
                if (field.hasAttribute(attribute)) {
                    field.setAttribute('data-segment-' + attribute,
                                       field.getAttribute(attribute));
                    field.removeAttribute(attribute);
                }
            });
            field.classList.remove('annotation-input');

            if (field.name) {
                // Radio groups are keyed on `name`; without the suffix, picking
                // an option on segment 2 would clear segment 1's.
                field.setAttribute('data-segment-name', field.name);
                field.name = field.name + suffix;
            }
        });

        // `annotation-form` ids are read by the form-level collectors too.
        root.querySelectorAll('form.annotation-form').forEach(function (form) {
            form.classList.remove('annotation-form');
            form.classList.add('segment-question-form');
        });
    }

    /** The scheme name a field belongs to, or null. */
    function schemeOf(field) {
        var holder = field.closest('[data-segment-scheme]');
        return holder ? holder.getAttribute('data-segment-scheme') : null;
    }

    /** The label a field answers under, falling back to its value. */
    function labelOf(field) {
        return field.getAttribute('data-segment-label_name') || field.value || '';
    }

    /** Write stored answers back into a freshly cloned form. */
    function populate(container, segment) {
        var stored = segment.annotations || {};

        container.querySelectorAll('input, select, textarea').forEach(function (field) {
            var scheme = schemeOf(field);
            if (!scheme || !(scheme in stored)) return;

            var answer = stored[scheme];
            if (field.type === 'checkbox') {
                var selected = Array.isArray(answer) ? answer : [answer];
                field.checked = selected.indexOf(labelOf(field)) !== -1;
            } else if (field.type === 'radio') {
                field.checked = (answer === labelOf(field));
            } else if (answer !== null && answer !== undefined
                       && typeof answer !== 'object') {
                field.value = answer;
            }
        });
    }

    /** Read the current form into `segment.annotations`. */
    function collect(container, segment) {
        var answers = {};

        container.querySelectorAll('input, select, textarea').forEach(function (field) {
            var scheme = schemeOf(field);
            if (!scheme) return;

            if (field.type === 'checkbox') {
                if (!field.checked) return;
                if (!Array.isArray(answers[scheme])) {
                    answers[scheme] = scheme in answers ? [answers[scheme]] : [];
                }
                answers[scheme].push(labelOf(field));
            } else if (field.type === 'radio') {
                if (field.checked) answers[scheme] = labelOf(field);
            } else if (field.value !== '') {
                answers[scheme] = field.value;
            }
        });

        segment.annotations = answers;
        return answers;
    }

    function bind(container, segment, onChange) {
        function handle() {
            collect(container, segment);
            if (typeof onChange === 'function') onChange(segment);
        }

        // `change` for discrete widgets, `input` for text and sliders so a
        // half-typed note is not lost when the annotator picks another segment.
        container.addEventListener('change', handle);
        container.addEventListener('input', handle);
    }

    window.SegmentQuestions = {
        render: renderSegmentQuestions,
        // Exported for tests; not part of the widget contract.
        _neutralize: neutralize,
        _collect: collect,
        _populate: populate,
    };

    if (typeof module !== 'undefined' && module.exports) {
        module.exports = window.SegmentQuestions;
    }
})();
